Employees
- id (int)
- name (varchar)
- role_id (int) -- Foreign key to Roles

Roles
- id (int)
- name (varchar)

Permissions
- id (int)
- name (varchar)

Role_Permissions (Junction Table)
- role_id (int)
- permission_id (int)
```

#### Express Middleware for Permissions
Instead of writing the database lookup logic inside every single route, you can create a reusable middleware function:

```javascript
// middleware/checkPermission.js
const db = require('../db');

function checkPermission(requiredPermission) {
    return (req, res, next) => {
        const userId = req.headers.userid; // Or better, extract from a JWT token

        // Join Employees, Roles, Role_Permissions, and Permissions to get user permissions
        const query = `
            SELECT p.name 
            FROM Employees e
            JOIN Role_Permissions rp ON e.role_id = rp.role_id
            JOIN Permissions p ON rp.permission_id = p.id
            WHERE e.id = ?
        `;

        db.query(query, [userId], (err, results) => {
            if (err) return res.status(500).json({ message: 'Database error.' });

            // Map the results to an array of permission strings
            const userPermissions = results.map(row => row.name);

            // Check if the required permission exists in the user's permissions
            if (!userPermissions.includes(requiredPermission)) {
                return res.status(403).json({ message: `Unauthorized. Requires ${requiredPermission} permission.` });
            }

            // If they have permission, move to the actual route handler
            next();
        });
    };
}

module.exports = checkPermission;
```

