const express = require('express');
const router = express.Router();
const { Custodian, LegalHold } = require('../models/associations');

// Create a new custodian
router.post('/', async (req, res) => {
  try {
    const newCustodian = await Custodian.create(req.body);
    res.status(201).json(newCustodian);
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Get all custodians
