  try {
    const custodians = await Custodian.findAll({ include: [{ model: LegalHold, as: 'legalHold' }] });
    res.json(custodians);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get a custodian by ID
router.get('/:id', async (req, res) => {
  try {
    const custodian = await Custodian.findByPk(req.params.id, { include: [{ model: LegalHold, as: 'legalHold' }] });
    if (custodian) {
      res.json(custodian);
    } else {
      res.status(404).json({ error: 'Custodian not found' });
    }
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Update a custodian by ID
router.put('/:id', async (req, res) => {
  try {
    const [updated] = await Custodian.update(req.body, { where: { id: req.params.id } });
    if (updated) {
      const updatedCustodian = await Custodian.findByPk(req.params.id, { include: [{ model: LegalHold, as: 'legalHold' }] });
      res.json(updatedCustodian);
    } else {
      res.status(404).json({ error: 'Custodian not found' });
    }
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Delete a custodian by ID
router.delete('/:id', async (req, res) => {
  try {
    const deleted = await Custodian.destroy({ where: { id: req.params.id } });
    if (deleted) {
      res.status(204).send('Custodian deleted');
    } else {
      res.status(404).json({ error: 'Custodian not found' });
    }
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

module.exports = router;
```

